// First 1000 digits of Pi after the decimal point
export const PI_DIGITS = "";

// Color map for digits following the example app pattern
export const DIGIT_COLORS: Record<string, string> = {
  '0': '#808080',  // Gray
  '1': '#FFFFFF',  // White
  '2': '#FFFF00',  // Yellow  
  '3': '#00FFFF',  // Cyan
  '4': '#00FF00',  // Green
  '5': '#DDA0DD',  // Lilac
  '6': '#9932CC',  // Purple
  '7': '#0080FF',  // Blue
  '8': '#FF8000',  // Orange
  '9': '#FF0000',  // Red
};

export const getDigitColor = (digit: string): string => {
  return DIGIT_COLORS[digit] || '#FFFFFF';
};

export const getDigitClass = (digit: string): string => {
  return `digit-${digit}`;
};

export const formatPiDisplay = (digits: string, currentIndex: number, showAll: boolean = false): string[] => {
  if (showAll) {
    return digits.split('');
  }
  return digits.slice(0, currentIndex).split('');
};
